/* Compact desk — free-form cards */
.desk {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.fillCol {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 4px 0 2px;
}

.toolbarLeft {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.toolbarTitle {
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.toolbarMeta {
  font-size: 11px;
  color: var(--text-tertiary);
}

.toolbarActions {
  display: flex;
  gap: 6px;
}

.bannerErr {
  padding: 8px 12px;
  border-radius: var(--r-md);
  background: var(--danger-50);
  color: var(--danger-700);
  border: 1px solid rgba(220, 38, 38, 0.18);
  font-size: var(--text-sm);
  font-weight: 600;
}

.meta {
  font-size: var(--text-xs);
  color: var(--text-tertiary);
}

.addRow {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--bg-subtle);
  flex-shrink: 0;
}

.addInput {
  flex: 1;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border-default);
  border-radius: var(--r-md);
  background: var(--bg-surface);
  font-size: 13px;
}

.addInput:focus {
  outline: none;
  border-color: var(--brand-400);
  box-shadow: var(--shadow-focus);
}

.tableWrap {
  overflow: auto;
  flex: 1;
  min-height: 0;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-sm);
}

.table th {
  position: sticky;
  top: 0;
  z-index: 1;
  text-align: left;
  padding: 7px 12px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
}

.table td {
  padding: 7px 12px;
  border-bottom: 1px solid var(--border-subtle);
  vertical-align: middle;
}

.table tbody tr:hover td {
  background: var(--bg-hover);
}

.tkBtn {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  color: inherit;
}

.tkBtn:hover .tk {
  color: var(--brand-600);
}

.tk {
  font-weight: 800;
  letter-spacing: -0.02em;
  font-family: var(--font-display);
}

.tkCell {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.rowEarn td {
  background: rgba(245, 158, 11, 0.05);
}

.rowEarn:hover td {
  background: rgba(245, 158, 11, 0.09) !important;
}

.earn {
  display: inline-block;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  padding: 1px 5px;
  border-radius: 4px;
  background: #fff7ed;
  color: #c2410c;
  border: 1px solid #fdba74;
  vertical-align: middle;
  line-height: 1.5;
  white-space: nowrap;
  cursor: pointer;
  font-family: inherit;
}

.earn:hover {
  filter: brightness(0.97);
}

.earnToday {
  background: #fef2f2;
  color: #b91c1c;
  border-color: #fca5a5;
  animation: earnPulse 1.6s ease-in-out infinite;
}

.earnSoon {
  background: #fff7ed;
  color: #c2410c;
  border-color: #fb923c;
}

.earnPast {
  background: #f1f5f9;
  color: #475569;
  border-color: #cbd5e1;
}

@keyframes earnPulse {
  0%,
  100% {
    box-shadow: 0 0 0 0 rgba(185, 28, 28, 0.25);
  }
  50% {
    box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.12);
  }
}

.rptBtn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0 3px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--brand-700);
  line-height: 1;
  opacity: 0.9;
}

.rptBtn:hover {
  opacity: 1;
  text-decoration: underline;
}

.chip {
  margin-left: 6px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--brand-700);
  background: var(--brand-50);
  border-radius: 4px;
  padding: 1px 5px;
  vertical-align: middle;
}

.actions {
  width: 36px;
  text-align: right;
}

.rm {
  width: 26px;
  height: 26px;
  border-radius: 6px;
  color: var(--text-muted);
  font-size: 16px;
  line-height: 1;
  border: none;
  background: transparent;
  cursor: pointer;
}

.rm:hover {
  background: var(--danger-50);
  color: var(--danger-700);
}

.empty {
  text-align: center;
  color: var(--text-tertiary);
  padding: 28px 14px !important;
}

.pulse {
  height: 100%;
  overflow: auto;
}

.pulsePre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-family: var(--font-sans);
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--text-secondary);
}

.emptyBlock {
  color: var(--text-tertiary);
  font-size: var(--text-sm);
}

.health {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.health li {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border-radius: var(--r-md);
  background: var(--bg-subtle);
  border: 1px solid var(--border-subtle);
}

.health span {
  color: var(--text-tertiary);
  font-size: var(--text-sm);
}

.health strong {
  font-size: var(--text-sm);
  font-weight: 700;
}
